import{_ as e,o as s,c as i,ag as t}from"./chunks/framework.Dn9Yy6J1.js";const k=JSON.parse('{"title":"版本與升級","description":"","frontmatter":{},"headers":[],"relativePath":"guide/versioning.md","filePath":"guide/versioning.md"}'),n={name:"guide/versioning.md"};function l(o,a,d,h,p,c){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="版本與升級" tabindex="-1">版本與升級 <a class="header-anchor" href="#版本與升級" aria-label="Permalink to &quot;版本與升級&quot;">​</a></h1><p>這篇說明設計系統的版本怎麼命名、去哪裡看每版改了什麼，以及使用端專案怎麼換到新版本。要升級設計系統、或想先試用還沒正式發布的改動時讀這篇。</p><h2 id="版本號" tabindex="-1">版本號 <a class="header-anchor" href="#版本號" aria-label="Permalink to &quot;版本號&quot;">​</a></h2><p>每個版本是 GitHub repo 上的一個 git tag。使用端安裝時，在網址的 <code>#</code> 後面指定 tag。</p><h3 id="正式版-vx-y-z" tabindex="-1">正式版：vX.Y.Z <a class="header-anchor" href="#正式版-vx-y-z" aria-label="Permalink to &quot;正式版：vX.Y.Z&quot;">​</a></h3><p>正式版的 tag 寫成 <code>vX.Y.Z</code>，例如 <code>v0.1.11</code>。使用端平常釘在正式版。</p><h3 id="預發布版-vx-y-z-beta-n" tabindex="-1">預發布版：vX.Y.Z-beta.N <a class="header-anchor" href="#預發布版-vx-y-z-beta-n" aria-label="Permalink to &quot;預發布版：vX.Y.Z-beta.N&quot;">​</a></h3><p>預發布版是某個正式版發布之前的試用版，tag 寫成 <code>vX.Y.Z-beta.N</code>：</p><ul><li><code>X.Y.Z</code> 是它之後要成為的正式版號。</li><li><code>N</code> 從 1 開始。同一個版號在正式發布前又有修改，就再打下一個號碼，例如 <code>v0.1.8-beta.1</code>、<code>v0.1.8-beta.2</code>、<code>v0.1.8-beta.3</code>，最後才是 <code>v0.1.8</code>。</li></ul><p>預發布版的用途是：改動還沒正式發布前，先讓使用端專案裝起來實際跑、確認沒問題。確認後發布正式版，使用端再把版本從預發布版換成正式版，例如從 <code>v0.1.8-beta.2</code> 換到 <code>v0.1.8</code>。</p><p>不是每個正式版之前都有預發布版。</p><h3 id="誰來打-tag" tabindex="-1">誰來打 tag <a class="header-anchor" href="#誰來打-tag" aria-label="Permalink to &quot;誰來打 tag&quot;">​</a></h3><p>目前預發布版與正式版的 tag 都是由維護者人工建立的。</p><h2 id="每版改了什麼" tabindex="-1">每版改了什麼 <a class="header-anchor" href="#每版改了什麼" aria-label="Permalink to &quot;每版改了什麼&quot;">​</a></h2><p>各版的版本說明在 <a href="https://github.com/Mendesky/mendesky-ds-angular/releases" target="_blank" rel="noreferrer">GitHub Releases</a>。文件網站上方導覽列的「版本說明」也會連過去。</p><p>升級前，先讀目前版本到目標版本之間每一版的說明。</p><h2 id="看對應版本的文件" tabindex="-1">看對應版本的文件 <a class="header-anchor" href="#看對應版本的文件" aria-label="Permalink to &quot;看對應版本的文件&quot;">​</a></h2><p>文件網站為每個正式版各保留一整套文件：</p><ul><li>右上角的版本選單可以切換版本。切換後會停在另一個版本的同一頁。</li><li>選單裡的 <code>main（開發中）</code> 是還沒發布的最新內容，不一定跟任何正式版相同。</li><li>網址的結構是 <code>/&lt;版本&gt;/</code> 為指南、<code>/&lt;版本&gt;/components/</code> 為元件頁。</li><li>直接打開文件網站首頁，會轉到最新的正式版。</li><li><code>v0.1.11</code> 以前的版本發布時還沒有文件網站，選單裡標「僅 README」，打開是該版當時的 README。</li></ul><p>使用端釘在哪一版，就看哪一版的文件，屬性與用法才會對得上。</p><h2 id="升級步驟" tabindex="-1">升級步驟 <a class="header-anchor" href="#升級步驟" aria-label="Permalink to &quot;升級步驟&quot;">​</a></h2><p>以下把 <code>vX.Y.Z</code> 換成要升到的版本。</p><h3 id="_1-指名安裝新版本" tabindex="-1">1. 指名安裝新版本 <a class="header-anchor" href="#_1-指名安裝新版本" aria-label="Permalink to &quot;1. 指名安裝新版本&quot;">​</a></h3><p>把 <code>package.json</code> 裡 <code>@mendesky/ds-angular</code> 的 tag 改成新版本，並用完整的套件來源指名安裝：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;github:Mendesky/mendesky-ds-angular#vX.Y.Z&quot;</span></span></code></pre></div><p>這個指令會同時更新 <code>package.json</code> 與 <code>package-lock.json</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;@mendesky/ds-angular&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;github:Mendesky/mendesky-ds-angular#vX.Y.Z&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>裝完打開 <code>package-lock.json</code>，找到 <code>node_modules/@mendesky/ds-angular</code> 這一筆，確認 <code>resolved</code> 結尾的 commit 已經換成新 tag 指向的 commit。</p><p>安裝結束時，postinstall 會自動刷新專案根目錄的 <code>mendesky-ds-angular</code> symlink，不用手動處理（設定方式見<a href="./getting-started.html">開始使用</a>）。</p><h3 id="_2-跑型別檢查與測試" tabindex="-1">2. 跑型別檢查與測試 <a class="header-anchor" href="#_2-跑型別檢查與測試" aria-label="Permalink to &quot;2. 跑型別檢查與測試&quot;">​</a></h3><p>設計系統是原始碼套件，新版的元件會跟你的專案一起編譯。換版後至少跑一次：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --noEmit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # 型別檢查</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --watch=false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 單元測試</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # 建置</span></span></code></pre></div><p>有錯誤時，對照該版的版本說明與新版的元件說明頁修正。</p><h3 id="_3-一起-commit" tabindex="-1">3. 一起 commit <a class="header-anchor" href="#_3-一起-commit" aria-label="Permalink to &quot;3. 一起 commit&quot;">​</a></h3><p><code>package.json</code> 與 <code>package-lock.json</code> 要放在同一個 commit。</p><h2 id="試用預發布版" tabindex="-1">試用預發布版 <a class="header-anchor" href="#試用預發布版" aria-label="Permalink to &quot;試用預發布版&quot;">​</a></h2><p>步驟跟升級一樣，只是 tag 換成預發布版：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;github:Mendesky/mendesky-ds-angular#vX.Y.Z-beta.N&quot;</span></span></code></pre></div><p>同一版號發布正式版後，再用同樣的方式換成正式版 <code>vX.Y.Z</code>。</p><h2 id="相關" tabindex="-1">相關 <a class="header-anchor" href="#相關" aria-label="Permalink to &quot;相關&quot;">​</a></h2><ul><li><a href="./getting-started.html">開始使用</a></li><li><a href="./contributing.html">貢獻</a></li><li><a href="./first-screen.html">第一個畫面</a></li></ul>`,41)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
